def backfill_legacy_registrations(apps, schema_editor):
    User = apps.get_model("users", "User")
    Registration = apps.get_model("registrations", "UserRegistration")
    AdministratorScope = apps.get_model("registrations", "AdministratorScope")
    ProductType = apps.get_model("registrations", "AgriculturalProductType")
    database = schema_editor.connection.alias

    status_map = {
        "PENDING": "SUBMITTED",
        "REJECTED": "REJECTED",
    }
    for user in User.objects.using(database).filter(
        role__in=("FARMER", "WHOLESALER", "RETAILER")
    ).iterator():
        Registration.objects.using(database).get_or_create(
            user_id=user.pk,
            defaults={
                "status": status_map.get(user.status, "APPROVED"),
                "legacy_registration": True,
                "submitted_at": user.created_at,
            },
        )

    for user in User.objects.using(database).filter(role="USER_ADMIN").iterator():
        AdministratorScope.objects.using(database).get_or_create(
            user_id=user.pk,
            defaults={"level": "GLOBAL", "location_id": None},
        )

    catalog = (
        ("tomato", "Tomato", "Vegetables"),
        ("potato", "Potato", "Root Crops"),
        ("onion", "Onion", "Vegetables"),
        ("green-pepper", "Green Pepper", "Vegetables"),
        ("carrot", "Carrot", "Root Crops"),
        ("yellow-maize", "Yellow Maize", "Grains"),
        ("white-teff", "White Teff", "Grains"),
        ("sesame-seed", "Sesame Seed", "Spices"),
        ("mango", "Mango", "Fruits"),
    )
    for code, name, category in catalog:
        ProductType.objects.using(database).get_or_create(
            code=code,
            defaults={"name": name, "category": category, "active": True},
        )


